/* order.h */
typedef struct order order;                 /* opaque: layout not visible */
order *order_new(const struct raw_order *raw, struct domain_error *err);
void   order_free(order *o);

/* order.c */
order *order_new(const struct raw_order *raw, struct domain_error *err) {
    if (raw->customer_id == NULL) { set_error(err, "customer required"); return NULL; }
    order *o = calloc(1, sizeof *o);
    o->id = order_id_new(); o->customer_id = strdup(raw->customer_id);
    return o;                               /* valid or NULL, never half-built */
}

